```java
package com.example.invoice-management.service;

import java.util.List;
import java.util.UUID;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.example.invoice-management.model.InvoiceHeader;
import com.example.invoice-management.model.InvoiceLine;
import com.example.invoice-management.repository.InvoiceHeaderRepository;
import com.example.invoice-management.repository.InvoiceLineRepository;

@Service
public class InvoiceService {

    @Autowired
    private InvoiceHeaderRepository invoiceHeaderRepository;

    @Autowired
    private InvoiceLineRepository invoiceLineRepository;

    public UUID createInvoice(InvoiceHeader invoiceHeader, List<InvoiceLine> invoiceLines) {
        InvoiceHeader savedInvoiceHeader = invoiceHeaderRepository.save(invoiceHeader);
        for (InvoiceLine invoiceLine : invoiceLines) {
            invoiceLine.setInvoiceNumber(savedInvoiceHeader.getInvoiceNumber());
            invoiceLineRepository.save(invoiceLine);
        }
        return UUID.randomUUID();
    }
}
```

