    } catch {
      case _: FileNotFoundException =>
        println(s"Archivo $filePath no encontrado.") case _: Exception =>
        println("Error al cargar el archivo CSV.") }
  }

  // Métodos antiguos: parseCsv, handleMissingValues y extractImportantFeaturesAndHandleDiversity

  def handleMissingValues(data: List[Empresario]): List[Empresario] = {
    def handleMissingValue[A](value: String, defaultValue: A): A = Try(value.toInt).getOrElse {
      Try(value.toDouble).getOrElse {
        if (value == "") None else Some(value)
      }.asInstanceOf[A]
    }

    data.map(empresario => Empresario(
      empresario.nombre,
      handleMissingValue(empresario.edad.toString, 0),
      empresario.género,
      empresario.industria,
      empresario.tamañoEmpresa,
      handleMissingValue(empresario.ubicación, None),
      empresario.éxito
    ))
  }
}
```

3. Identificar posibles sesgos: Para identificar posibles sesgos, debemos utilizar técnicas de exploración de datos y visualización, tales como histogramas, boletos y gráficos de dispersión. Implicaremos dos técnicas comunes:

