4. Extraer las 5 características más importantes: Ahora, debemos utilizar técnicas de selección de características para elegir las 5 características más importantes que reflejen mejor la diversidad del conjunto de datos, mientras se toman en cuenta los posibles sesgos. Se pueden utilizar métodos estadísticos como la cuantilización, el alfa-índice de Simpson o la entropía para elegir las características clave.

```scala
import java.util.Comparator

case class FeatureImportance(
  feature: String,
  importanceScore: Double
)

object Main {
  def main(args: Array[String]): Unit = {
    val filePath = "empresarios.csv"
    try {
      val data = parseCsv(filePath)
      data = handleMissingValues(data)
      val aggregatedData = groupData(data, Seq("género", "industria"))

      val featureImportances = selectImportantFeatures(aggregatedData)
      featureImportances.sortBy(-_importanceScore).take(5).foreach(println)
    } catch {
      case _: FileNotFoundException =>
        println(s"Archivo $filePath no encontrado.") case _: Exception =>
        println("Error al cargar el archivo CSV.") }
  }

  // Métodos anteriores: parseCsv, handleMissingValues, groupData

  def selectImportantFeatures(aggregatedData: Map[String, AggregatedData[Boolean]]): List[FeatureImportance] = {
    def calculateSD(data: List[Double]): Double = math.sqrt(data.map(d => math.pow(d - data.mean, 2)).sum / data.length)

    val importanceFunctions = Seq(
      (aggregatedData, "Género", calculateSimpsonIndex),
      (aggregatedData, "Industria", calculateSD)
    )

    importanceFunctions.map { case ((aggregatedData, characteristic), importanceFunction) =>
      val featureImportance = importanceFunction(aggregatedData(characteristic).values.values)
      FeatureImportance(characteristic, featureImportance)
    }.toList
  }

  def calculateSimpsonIndex(values: Seq[Seq[Double]]): Double = {
    val totalCount = values.flatMap(_).distinct.length
    values.map(values => values.distinct.length.toDouble / values.length).product.toDouble / totalCount
  }

  def calculateSD(data: Seq[Seq[Double]]): Double = {
    val columnMeans = data.map(_ map (_.mean)).transpose
    columnMeans.map(c => calculateSD(c)).max
  }
}
```

Aquí, se utilizan dos funciones para calcular la importancia de características: una basada en el índice de Simpson y otra en la desviación estándar. Después, se ordenan las características por importancia y se imprimen las 5 características más importantes.

