    static void Main()
    {
        string input = Console.ReadLine().ToLower(); // Convertimos la entrada del usuario a minúsculas para facilitar la búsqueda

        // Agregamos los sentimientos que deseas identificar
        if (input.Contains("schadenfreude"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es schadenfreude.");
        }
        else if (input.Contains("ennui"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es ennui.");
        }
        else if (input.Contains("weltschmerz"))
        {
            Console.WriteLine("El sentimiento en el que estás pensando es weltschmerz.");
        }
        else if (input.Contains("empathy gap")
            || input.Contains("beatific resignation")
            || input.Contains("ennui noir")
            || input.Contains("désœuvrement")
            || input.Contains("malaise")
            || input.Contains("existential dread")
            || input.Contains("Sonderweg")
