        }
        else
        {
            Console.WriteLine("Lo siento, no estoy familiarizado con ese sentimiento. ¿Puedes proporcionar más información?");
        }
    }
}
```

Este programa puede identificar los sentimientos `schadenfreude`, `ennui`, `weltschmerz`, así como otros sentimientos como:

