      head = null;
      tail = null;
    } else {
      head = head.next;
      head.prev = null;
    }
    oldHead.next = null;
    oldHead.prev = null;
    size--;
  }

  void seeSaw() {
    int sum = 0;
    Node current = head;
    while (current != null) {
      sum += current.value + 1;
      current = current.next.next;
    }
