class BurstQueue:
    def __init__(self):
        self.items = []
        self.tree = []  # árbol binario para `seeSaw()`

    def is_empty(self):
        return not self.items

    def enqueue(self, x):
        self.items.append(x)
        self._update_tree(x, 1)

    def dequeue(self):
        if not self.items:
            return None
        x = self.items.pop(0)
        self._update_tree(x, -1)
        return x

    def see_saw(self):
        frac_sum = 0
        for node in self.tree:
            frac_sum += node[0] / node[1]
        return frac_sum

    def _update_tree(self, x, value):
        """Actualiza el árbol binario con el nuevo elemento"""
        if not self.tree:
            self.tree.append((x, value))
        else:
            self._insert_node(x, value, 0, len(self.tree)-1)

    def _insert_node(self, x, value, start, end):
        if start == end:
            node_idx = start
            self.tree[node_idx] = (x, value + self.tree[node_idx][1])
            return

        mid = (start + end) // 2
        if x < self.tree[mid][0]:
            self._insert_node(x, value, start, mid)
        else:
            self._insert_node(x, value, mid+1, end)

        self.tree = self._merge_nodes(start, end)

    def _merge_nodes(self, start, end):
        """Merged two distinct subarrays"""
        if start > end:
            return self.tree

        if start == end:
            return [self.tree[start]]

        mid = (start + end) // 2
        left = self._merge_nodes(start, mid)
        right = self._merge_nodes(mid+1, end)

        merged = []
        I = j = 0
        while I < len(left) and j < len(right):
            if left[i][0] <= right[j][0]:
                merged.append(left[i])
                I += 1
            else:
                merged.append(right[j])
                j += 1

        merged += left[i:]
        merged += right[j:]

        return merged
```

