import java.util.*;

public class BurstQueue {
    private int[] items;
    private Node[] tree;

    public BurstQueue(int capacity) {
        this.items = new int[capacity];
        this.tree = new Node[capacity];
    }

    public boolean isEmpty() {
        return items.length == 0;
    }

    public void enqueue(int x) {
        if (items.length == tree.length) {
            throw new RuntimeException("Queue is full");
        }
        items[items.length - 1] = x;
        if (tree.length == 0) {
            tree[0] = new Node(x, 1);
        } else {
            _insertNode(x, 1, 0, tree.length - 1);
        }
        Arrays.copyOfRange(items, 1, items.length);
        Arrays.copyOfRange(tree, 1, tree.length);
    }

    public int dequeue() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        int x = items[0];
        if (tree.length == 1) {
            tree[0] = null;
        } else {
            _removeNode(0, tree.length - 2);
        }
        Arrays.copyOfRange(items, 1, items.length);
        Arrays.copyOfRange(tree, 1, tree.length);
        return x;
    }

    public double seeSaw() {
        double fracSum = 0;
        for (Node node : tree) {
            fracSum += node.value / node.denom;
        }
        return fracSum;
    }

    private void _insertNode(int x, int value, int start, int end) {
        if (start == end) {
            int nodeIndex = start;
            tree[nodeIndex] = new Node(x, value + tree[nodeIndex].denom);
            return;
        }

        int mid = (start + end) / 2;
        if (x < tree[mid].value) {
            _insertNode(x, value, start, mid);
        } else {
            _insertNode(x, value, mid + 1, end);
        }

        tree = _mergeNodes(start, end);
    }

    private Node[] _mergeNodes(int start, int end) {
        if (start > end) {
            return tree;
        }

        if (start == end) {
            Node[] nodes = new Node[1];
            nodes[0] = tree[start];
            return nodes;
        }

        int mid = (start + end) / 2;
        Node[] left = _mergeNodes(start, mid);
        Node[] right = _mergeNodes(mid + 1, end);
        Node[] merged = new Node[left.length + right.length];
        int I = 0, j = 0, k = 0;

        while (i < left.length && j < right.length) {
            if (left[i].value <= right[j].value) {
                merged[k] = left[i];
                i++;
            } else {
                merged[k] = right[j];
                j++;
            }
            k++;
        }

        System.arraycopy(left, i, merged, k, left.length - i);
        System.arraycopy(right, j, merged, k + (left.length - i), right.length - j);

        return merged;
    }

    private static class Node {
        int value;
        int denom;

        public Node(int value, int denom) {
            this.value = value;
            this.denom = denom;
        }
    }
}
```

