           requireExplicitNew: true,
         },
       ],
       'vue/prefer-exported-function': 'error',
       'vue/prefer-todos': 'error',

       // Regla personalizada para comprobar la modificación del estado interno del componente en el hook `updated`
       'vue/updated-component-state-modification': {
