                   '(\\w+|_\\w+)(\\s*\\([^\\)]*\\))?\\s*\\{',
                 message: 'Método en el hook updated debe ser puramente de lectura.',
               },
             ],
           },
           {
             name: 'callbacks', // Prohibir llamadas a métodos que modifiquen estado interno del componente
             options: [
               {
                 pattern:
                   '\\b(\\w+|_\\w+)(\\s*\\([^\\)]*\\))\\s*\\.\\s*(\\w+|_\\w+|\\.\w+|\\[\\w\\s\\]]|\\(\\s*[^\\)]*\\))\\s*\\(',
                 message:
